<?php
declare(strict_types=1);
// Page: ?page=projects — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 require_perm('manage_projects'); $db=portal_pdo(); $edit=null; $selected=[]; if(isset($_GET['id'])){ $st=$db->prepare('SELECT * FROM portal_projects WHERE id=?'); $st->execute([(int)$_GET['id']]); $edit=$st->fetch(); if($edit) $selected=project_channel_ids((int)$edit['id']); } if($_SERVER['REQUEST_METHOD']==='POST'){ $token=make_confirmation('save_project',['id'=>$_POST['id']??null,'data'=>$_POST['data']??[],'channels'=>$_POST['channels']??[],'return_to'=>'?page=projects']); redirect('?page=confirm&token='.$token); } layout_start('Project Management'); $channels=all_channels(); $rows=$db->query('SELECT * FROM portal_projects ORDER BY id DESC')->fetchAll(); ?><div class="row g-3"><div class="col-lg-4"><div class="cardx"><h3><?= $edit?'Edit Project':'Add Project' ?></h3><p class="text-muted">Link each project to one or more USSD/IVR channels through the short code.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Project Name</label><input class="form-control mb-2" name="data[project_name]" value="<?=e($edit['project_name']??'')?>" placeholder="VAS Main Menu Upgrade"><label>Primary Short Code</label><input class="form-control mb-2" name="data[short_code]" value="<?=e($edit['short_code']??'')?>" placeholder="*123#"><label>Status</label><select class="form-select mb-2" name="data[status]"><?php foreach(['Planning','Development','Testing','Launched','Completed','Suspended'] as $v):?><option value="<?=e($v)?>" <?=($edit['status']??'Planning')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><div class="row g-2"><div class="col-md-6"><label>Start Date</label><input type="date" class="form-control mb-2" name="data[start_date]" value="<?=e($edit['start_date']??'') ?>"></div><div class="col-md-6"><label>Launch Date</label><input type="date" class="form-control mb-2" name="data[launch_date]" value="<?=e($edit['launch_date']??'') ?>"></div></div><label>Description</label><textarea class="form-control mb-2" name="data[description]" rows="3"><?=e($edit['description']??'')?></textarea><label>Linked Channels</label><div class="channel-picker mb-3"><?php foreach($channels as $c):?><label class="channel-choice"><input type="checkbox" name="channels[]" value="<?=e($c['id'])?>" <?=in_array((int)$c['id'],$selected,true)?'checked':''?>> <span><b><?=e($c['channel_type'])?> <?=e($c['short_code'])?></b><small><?=e($c['service_name'])?> • <?=e($c['provider'])?></small></span></label><?php endforeach;?></div><button class="btn btn-primary w-100">Preview & Confirm Save</button><?php if($edit):?><a class="btn btn-outline-secondary w-100 mt-2" href="?page=projects">Cancel Edit</a><?php endif;?></form></div></div><div class="col-lg-8"><div class="cardx"><div class="d-flex justify-content-between align-items-center"><h3>Project Register</h3><span class="badge bg-primary"><?=count($rows)?> projects</span></div><div class="table-scroll"><table class="table table-hover"><thead><tr><th>Project Name</th><th>Primary Short Code</th><th>Status</th><th>Start</th><th>Launch</th><th>Linked Channels</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['project_name'])?></strong><div class="text-muted small"><?=e(mb_strimwidth((string)$r['description'],0,90,'...'))?></div></td><td><?=e($r['short_code'])?></td><td><span class="badge status-<?=e(strtolower($r['status']))?>"><?=e($r['status'])?></span></td><td><?=e($r['start_date'])?></td><td><?=e($r['launch_date'])?></td><td><?=e(project_channels_label((int)$r['id']))?></td><td class="sticky-actions"><a class="btn btn-sm btn-warning" href="?page=projects&id=<?=e($r['id'])?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php layout_end(); exit;
